import{_ as l,a0 as p,w as r,s as o,I as a,x as s,a1 as n,A as t,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const I=JSON.parse('{"title":"如何在 RHEL 8 上安装 FreeIPA 服务器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 RHEL 8 上安装 FreeIPA 服务器 | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 RHEL 8 上安装 FreeIPA 服务器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 RHEL 8 上安装 FreeIPA 服务器 | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20230415.0 ⭐️⭐️ How to Install FreeIPA Server on RHEL 8  Rocky Linux 8  AlmaLinux 8","title":"如何在 RHEL 8 上安装 FreeIPA 服务器","tag":"202305","desc":""},"relativePath":"202305/20230415.0 ⭐️⭐️ How to Install FreeIPA Server on RHEL 8  Rocky Linux 8  AlmaLinux 8.md","filePath":"[post].md"}'),h={name:"202305/20230415.0 ⭐️⭐️ How to Install FreeIPA Server on RHEL 8  Rocky Linux 8  AlmaLinux 8.md"};function c(u,e,g,k,b,m){const i=p("Link");return r(),o("div",null,[e[17]||(e[17]=a("h1",{id:"如何在-rhel-8-上安装-freeipa-服务器",tabindex:"-1"},[s("如何在 RHEL 8 上安装 FreeIPA 服务器 "),a("a",{class:"header-anchor",href:"#如何在-rhel-8-上安装-freeipa-服务器","aria-label":"Permalink to “如何在 RHEL 8 上安装 FreeIPA 服务器”"},"​")],-1)),e[18]||(e[18]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202305/05/160246m3vu7phhy7eyuo7j.png",alt:""})],-1)),e[19]||(e[19]=a("p",null,"你是否正在寻找有关如何在 Linux 上安装 FreeIPA 服务器的简单指南？",-1)),e[20]||(e[20]=a("p",null,"此页面上的分步指南将展示如何在 RHEL 8、Rocky Linux 8 和 AlmaLinux 8 上安装 FreeIPA 服务器。",-1)),a("p",null,[n(i,{href:"https://www.freeipa.org/page/Main_Page"},{default:t(()=>[...e[0]||(e[0]=[s("FreeIPA",-1)])]),_:1}),e[1]||(e[1]=s(" 是一个自由开源的基于 Linux 系统的集中式身份和访问管理工具，它是 Red Hat 身份管理器的上游项目。使用 FreeIPA，我们可以轻松地管理集中式身份验证以及帐户管理、策略（基于主机的访问控制）和审计。",-1))]),e[21]||(e[21]=d(`<p>FreeIPA 基于以下开源项目：</p><ul><li>LDAP 服务器 – 基于 389 项目</li><li>KDC – 基于 MIT Kerberos 实现</li><li>基于 Dogtag 项目的 PKI</li><li>用于活动目录集成的 Samba 库</li><li>基于 BIND 和 Bind-DynDB-LDAP 插件的 DNS 服务器</li><li>NTP</li></ul><h3 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to “先决条件”">​</a></h3><ul><li>预装 RHEL 8 或 Rocky Linux 8 或 AlmaLinux 8</li><li>具有管理员权限的 Sudo 用户</li><li>内存 = 2 GB</li><li>CPU = 2 个 vCPU</li><li>磁盘 = 根目录有 12GB 可用空间</li><li>互联网连接</li></ul><h3 id="freeipa-的实验室详细信息" tabindex="-1">FreeIPA 的实验室详细信息 <a class="header-anchor" href="#freeipa-的实验室详细信息" aria-label="Permalink to “FreeIPA 的实验室详细信息”">​</a></h3><ul><li>IP 地址 = 192.168.1.102</li><li>Hostanme = ipa.linuxtechi.lan</li><li>操作系统：RHEL 8 或 Rocky Linux 8 或 AlmaLinux 8</li></ul><p>事不宜迟，让我们深入了解 FreeIPA 安装步骤。</p><h3 id="_1、设置主机名并安装更新" tabindex="-1">1、设置主机名并安装更新 <a class="header-anchor" href="#_1、设置主机名并安装更新" aria-label="Permalink to “1、设置主机名并安装更新”">​</a></h3><p>打开服务器的终端并使用 <code>hostnamectl</code> 命令设置主机名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo hostnamectl set-hostname &quot;ipa.linuxtechi.lan&quot;</span></span>
<span class="line"><span>$ exec bash</span></span></code></pre></div><p>使用 <code>yum</code>/<code>dnf</code> 命令安装更新，然后重新启动：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf update -y</span></span>
<span class="line"><span>$ sudo reboot</span></span></code></pre></div><h3 id="_2、更新主机文件并将-selinux-设置为许可" tabindex="-1">2、更新主机文件并将 SELinux 设置为许可 <a class="header-anchor" href="#_2、更新主机文件并将-selinux-设置为许可" aria-label="Permalink to “2、更新主机文件并将 SELinux 设置为许可”">​</a></h3><p>运行以下 <code>tee</code> 命令更新 <code>/etc/hosts</code> 文件，根据你的设置替换 IP 地址和主机名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo -e &quot;192.168.1.102\\tipa.linuxtechi.lan\\t ipa&quot; | sudo tee -a /etc/hosts</span></span></code></pre></div><p>将 SELinux 设置为许可，运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo setenforce 0</span></span>
<span class="line"><span>$ sudo sed -i &#39;s/^SELINUX=.*/SELINUX=permissive/g&#39; /etc/selinux/config</span></span>
<span class="line"><span>$ getenforce</span></span>
<span class="line"><span>Permissive</span></span></code></pre></div><h3 id="_3、安装-freeipa-及其组件" tabindex="-1">3、安装 FreeIPA 及其组件 <a class="header-anchor" href="#_3、安装-freeipa-及其组件" aria-label="Permalink to “3、安装 FreeIPA 及其组件”">​</a></h3><p>Appstream 包仓库中提供了 FreeIPA 包及其依赖项。由于我们计划安装集成 DNS 的 FreeIPA，因此我们还将安装 <code>ipa-server-dns</code> 和 <code>bind-dyndb-ldap</code>。</p><p>运行以下命令安装 FreeIPA 及其依赖项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf -y install @idm:DL1</span></span>
<span class="line"><span>$ sudo dnf install freeipa-server ipa-server-dns bind-dyndb-ldap -y</span></span></code></pre></div><h3 id="_4、开始安装-freeipa" tabindex="-1">4、开始安装 FreeIPA <a class="header-anchor" href="#_4、开始安装-freeipa" aria-label="Permalink to “4、开始安装 FreeIPA”">​</a></h3><p>成功安装 FreeIPA 包及其依赖项后，使用以下命令启动 FreeIPA 安装设置。</p><p>它将提示几件事，例如配置集成 DNS、主机名、域名和领域名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ipa-server-install</span></span></code></pre></div><p>上述命令的输出如下所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/11/IPA-Server-Install-Command-RHEL-RockyLinux-AlmaLinux.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/11/IPA-Install-Directory-Manager-IPA-Admin-Password.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>在上面的窗口中输入 “yes” 后，需要一些时间来配置你的 FreeIPA 服务器，设置成功后，我们将得到下面的输出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/11/IPA-Installation-Successful-Message-RHEL-AlmaLinux-RockyLinux.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>以上输出确认 FreeIPA 已成功安装。</p><h3 id="_5、在防火墙中允许-freeipa-端口" tabindex="-1">5、在防火墙中允许 FreeIPA 端口 <a class="header-anchor" href="#_5、在防火墙中允许-freeipa-端口" aria-label="Permalink to “5、在防火墙中允许 FreeIPA 端口”">​</a></h3><p>如果正在你的服务器上运行系统防火墙，那么运行如下 <code>firewall-cmd</code> 命令以允许 FreeIPA 端口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --add-service={http,https,dns,ntp,freeipa-ldap,freeipa-ldaps} --permanent</span></span>
<span class="line"><span>$ sudo firewall-cmd --reload</span></span></code></pre></div><h3 id="_6、访问-freeipa-管理门户" tabindex="-1">6、访问 FreeIPA 管理门户 <a class="header-anchor" href="#_6、访问-freeipa-管理门户" aria-label="Permalink to “6、访问 FreeIPA 管理门户”">​</a></h3><p>执行下面的 <code>ipactl</code> 命令查看 FreeIPA 的所有服务是否都在运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ipactl status</span></span>
<span class="line"><span>You must be root to run ipactl.</span></span>
<span class="line"><span>$ sudo ipactl status</span></span>
<span class="line"><span>Directory Service: RUNNING</span></span>
<span class="line"><span>krb5kdc Service: RUNNING</span></span>
<span class="line"><span>kadmin Service: RUNNING</span></span>
<span class="line"><span>named Service: RUNNING</span></span>
<span class="line"><span>httpd Service: RUNNING</span></span>
<span class="line"><span>ipa-custodia Service: RUNNING</span></span>
<span class="line"><span>pki-tomcatd Service: RUNNING</span></span>
<span class="line"><span>ipa-otpd Service: RUNNING</span></span>
<span class="line"><span>ipa-dnskeysyncd Service: RUNNING</span></span>
<span class="line"><span>ipa: INFO: The ipactl command was successful</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>让我们使用 <code>kinit</code> 命令验证管理员用户是否会通过 Kerberos 获取令牌，使用我们在 FreeIPA 安装期间提供的相同管理员用户密码。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kinit admin</span></span>
<span class="line"><span>$ klist</span></span></code></pre></div><p>以上命令的输出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/11/FeeIPA-kinit-admin-token.png" alt=""></p><p>完美，上面的输出确认管理员获得了令牌。现在，尝试访问 FreeIPA Web 控制台，在网络浏览器上输入以下 URL：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://ipa.linuxtechi.lan/ipa/ui</span></span></code></pre></div><p>或者</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://&lt;Server-IPAddress&gt;/ipa/ui</span></span></code></pre></div><p>使用我们在安装过程中指定的用户名 <code>admin</code> 和密码。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/11/Accept-Risk-FreeIPA-WebConsole-URL-1024x556.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>对于 FreeIPA Web 控制台，使用自签名 SSL 证书，这就是我们看到此窗口的原因，因此单击“<ruby>接受风险并继续<rt>Accept the Risk and Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/11/FreeIPA-Login-Page-RHEL-RockyLinux-AlmaLinux-1024x586.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>输入凭据后，单击“<ruby>登录<rt>Log in</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/11/FreeIPA-Dashboard-RHEL-RockyLinux-AlmaLinux-1024x585.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>这证实我们已在 RHEL 8/Rocky Linux 8 / AlmaLinux8 上成功设置 FreeIPA。</p><p>这就是全部，我希望你觉得它提供了很多信息。请在下面的评论部分中发表你的疑问和反馈。</p><p><em>（题图：MJ/9df57ea0-b5a0-48f9-a323-853a28ca6162）</em></p><hr>`,55)),a("p",null,[e[3]||(e[3]=s("via: ",-1)),n(i,{href:"https://www.linuxtechi.com/install-freeipa-rhel-rocky-almalinux/"},{default:t(()=>[...e[2]||(e[2]=[s("https://www.linuxtechi.com/install-freeipa-rhel-rocky-almalinux/",-1)])]),_:1})]),a("p",null,[e[8]||(e[8]=s("作者：",-1)),n(i,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>[...e[4]||(e[4]=[s("Pradeep Kumar",-1)])]),_:1}),e[9]||(e[9]=s(" 选题：",-1)),n(i,{href:"https://github.com/lkxed/"},{default:t(()=>[...e[5]||(e[5]=[s("lkxed",-1)])]),_:1}),e[10]||(e[10]=s(" 译者：",-1)),n(i,{href:"https://github.com/geekpi"},{default:t(()=>[...e[6]||(e[6]=[s("geekpi",-1)])]),_:1}),e[11]||(e[11]=s(" 校对：",-1)),n(i,{href:"https://github.com/wxy"},{default:t(()=>[...e[7]||(e[7]=[s("wxy",-1)])]),_:1})]),a("p",null,[e[14]||(e[14]=s("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[12]||(e[12]=[s("LCTT",-1)])]),_:1}),e[15]||(e[15]=s(" 原创编译，",-1)),n(i,{href:"https://linux.cn/"},{default:t(()=>[...e[13]||(e[13]=[s("Linux中国",-1)])]),_:1}),e[16]||(e[16]=s(" 荣誉推出",-1))])])}const P=l(h,[["render",c]]);export{I as __pageData,P as default};
